def main():
    products = fetch_products()
    print(f"Fetched {len(products)} products\n")

    updated = 0
    for p in products:
        slug = p.get("slug", "")
        pid = p.get("id", "")

        updates = {}

        # SEO title (en)
        if slug in SEO_TITLES_EN:
            updates["seo_title_en"] = SEO_TITLES_EN[slug]
        if slug in SEO_TITLES_ZH:
            updates["seo_title_zh"] = SEO_TITLES_ZH[slug]

        # Description opening sentences
        if slug in DESC_OPENINGS_EN:
            # Prepend the conclusion sentence to existing description
            old_desc = p.get("description_en", "") or ""
            if old_desc and not old_desc.startswith(DESC_OPENINGS_EN[slug][:60]):
                updates["description_en"] = DESC_OPENINGS_EN[slug] + "\n\n---\n\n" + old_desc
            elif not old_desc:
                updates["description_en"] = DESC_OPENINGS_EN[slug]

        if slug in DESC_OPENINGS_ZH:
            old_desc_zh = p.get("description_zh", "") or ""
            if old_desc_zh and not old_desc_zh.startswith(DESC_OPENINGS_ZH[slug][:60]):
                updates["description_zh"] = DESC_OPENINGS_ZH[slug] + "\n\n---\n\n" + old_desc_zh
            elif not old_desc_zh:
                updates["description_zh"] = DESC_OPENINGS_ZH[slug]

        # FAQ (en/zh)
        if slug in FAQS_EN:
            faq_json = [{"q": q, "a": a} for q, a in FAQS_EN[slug]]
            updates["faq_en"] = json.dumps(faq_json, ensure_ascii=False)
        if slug in FAQS_EN:
            faq_json_zh = [{"q": q, "a": a} for q, a in FAQS_EN[slug]]
            updates["faq_zh"] = json.dumps(faq_json_zh, ensure_ascii=False)

        if updates:
            print(f"  Updating {slug}... ({len(updates)} fields)")
            result = update_product(pid, updates)
            if result:
                updated += 1
                print(f"    OK")
            else:
                print(f"    FAILED")
        else:
            print(f"  SKIP {slug} (no data)")

    print(f"\nDone. Updated {updated}/{len(products)} products.")

if __name__ == "__main__":
    main()
